-- Up to twenty grouped source-row patterns for the selected account and month, highest score first. Contains unflagged rows too. source_row_fingerprint identifies content, not a transaction ID; duplicate_multiplicity preserves repetitions. All account totals must come from get_account_snapshot.
SELECT *, COUNT(*) OVER () AS total_evidence_groups FROM finance.agent_demo_fs.transaction_evidence_sql WHERE snapshot_id = (SELECT snapshot_id FROM finance.agent_demo_fs.snapshot_metadata_sql WHERE status = 'READY') AND period_key = CASE WHEN CAST({{period_key}} AS INT) = 0 THEN (SELECT MAX(period_key) FROM finance.agent_demo_fs.portfolio_monthly_sql WHERE snapshot_id = (SELECT snapshot_id FROM finance.agent_demo_fs.snapshot_metadata_sql WHERE status = 'READY')) ELSE CAST({{period_key}} AS INT) END AND account_id = CONCAT('ACC', LPAD(CAST(CAST({{account_number}} AS BIGINT) AS STRING), 8, '0')) ORDER BY risk_score DESC, gross_amount_inr DESC, transaction_date DESC, source_row_fingerprint LIMIT 20
